"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["56178"],{33709(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.banca.modo_de_deliberacao_invalido","status":422,"titulo":"O modo de delibera\xe7\xe3o da banca deve ser colegiada com vota\xe7\xe3o ou ato individual"},"descricao":{"codigo":"uniplus.selecao.banca.modo_de_deliberacao_invalido","requisitos":["UNI-REQ-0275","UNI-REQ-0338"],"oQueAconteceu":["A regra de delibera\xe7\xe3o da banca informou um `modo` que n\xe3o pertence ao vocabul\xe1rio\\nde delibera\xe7\xe3o. O vocabul\xe1rio \xe9 fechado e tem dois modos:","- `colegiadaComVotacao`: a banca decide por vota\xe7\xe3o, com qu\xf3rum, crit\xe9rio de\\n  decis\xe3o e forma de encerramento (UNI-REQ-0275);\\n- `atoIndividual`: sem qu\xf3rum nem vota\xe7\xe3o, qualquer pessoa titular designada\\n  pratica o ato (UNI-REQ-0338).","O modo escolhido define quais campos da regra existem. Um valor fora do\\nvocabul\xe1rio n\xe3o permite saber como a banca decide nem o que conferir na\\ndeclara\xe7\xe3o.","A recusa vem na lista `errors[]` da resposta, no caminho do campo recusado, por exemplo `fases[0].bancasRequeridas[0].regraDeDeliberacao.modo` na banca da fase e `etapas[0].bancas[0].regraDeDeliberacao.modo` na banca da etapa."],"comoResolver":["Informe um dos dois modos. Use `colegiadaComVotacao` quando o edital manda a banca\\nvotar e `atoIndividual` quando o edital d\xe1 a decis\xe3o a quem pratica o ato\\nsozinho, como na banca de homologa\xe7\xe3o das inscri\xe7\xf5es. Depois de corrigido o modo,\\nos campos dele s\xe3o conferidos; no ato individual, a presen\xe7a de campo de vota\xe7\xe3o\\ntem [recusa pr\xf3pria](/erros/uniplus.selecao.banca.ato_individual_sem_votacao)."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo","Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Banca"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);